package pe.edu.upeu.pago.service;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import java.util.*;import java.math.BigDecimal;import java.time.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import org.springframework.test.util.ReflectionTestUtils;
import pe.edu.upeu.pago.entity.*;import pe.edu.upeu.pago.client.*;import pe.edu.upeu.pago.repository.*;
@ExtendWith(MockitoExtension.class) class ConciliacionPagoServiceTest {
 @Mock OrdenCompraRepository ordenes;@Mock OrdenCertificadoRepository certificados;@Mock MovimientoSaldoRepository movimientos;@Mock MercadoPagoClient mp;@Mock LiquidacionService liquidaciones;@Mock BloqueoSaldoService bloqueo;@Mock ReembolsoRepository reembolsos;@Mock InscripcionClient inscripciones;
 ConciliacionPagoService service;OrdenCompra o;MovimientoSaldo m;
 @BeforeEach void setup(){Clock clock=Clock.fixed(Instant.parse("2026-10-27T15:00:00Z"),ZoneId.of("America/Lima"));service=new ConciliacionPagoService(ordenes,certificados,movimientos,mp,liquidaciones,bloqueo,clock,reembolsos,inscripciones);ReflectionTestUtils.setField(service,"dias",7L);o=new OrdenCompra();o.setId(42L);o.setDocenteId(7L);o.setMontoTotal(new BigDecimal("100"));o.setMontoDocente(new BigDecimal("80"));o.setMercadoPagoPaymentId("123");o.setEstado(OrdenCompra.EstadoOrden.APROBADA);o.setFechaAprobacion(LocalDateTime.of(2026,10,1,10,0));m=new MovimientoSaldo();m.setDocenteId(7L);m.setMonto(new BigDecimal("80"));m.setEstado(MovimientoSaldo.EstadoMovimiento.PENDIENTE);when(ordenes.docenteDe(42L)).thenReturn(Optional.of(7L));when(ordenes.bloquear(42L)).thenReturn(Optional.of(o));when(movimientos.findByOrdenIdAndTipo(42L,MovimientoSaldo.TipoMovimiento.VENTA)).thenReturn(Optional.of(m));}
 void pago(String estado,String fondos){when(mp.obtenerPago("123")).thenReturn(new MercadoPagoClient.PagoExterno("123",estado,"42","100","PEN",new BigDecimal("5"),new BigDecimal("95"),fondos,"2026-10-08T10:00:00-05:00",BigDecimal.ZERO));}
 @Test void fondosPendientesNoSeLiberanPorTiempo(){pago("approved","pending");service.compra(42L);assertTrue(m.isConciliado());assertEquals(MovimientoSaldo.EstadoMovimiento.PENDIENTE,m.getEstado());}
 @Test void fondosLiberadosYCumplidoPlazoSonDisponibles(){pago("approved","released");service.compra(42L);assertEquals(MovimientoSaldo.EstadoMovimiento.DISPONIBLE,m.getEstado());assertEquals(new BigDecimal("80"),m.getMonto());assertEquals(new BigDecimal("5"),o.getCostoProcesamiento());assertEquals(new BigDecimal("95"),o.getNetoRecibido());}
 @Test void disputaAnulaReservasSinPagar(){pago("in_mediation","blocked");service.compra(42L);assertEquals(MovimientoSaldo.EstadoMovimiento.BLOQUEADO,m.getEstado());verify(liquidaciones).bloquearPendientes(eq(7L),anyString());}
 @Test void contracargoRevierteCreditoYMarcaRevocacion(){pago("charged_back","blocked");service.compra(42L);assertEquals(OrdenCompra.EstadoOrden.CONTRACARGO,o.getEstado());assertTrue(o.isRequiereRevocacion());assertEquals(MovimientoSaldo.EstadoMovimiento.REVERTIDO,m.getEstado());verify(liquidaciones).bloquearPendientes(eq(7L),anyString());}
 @Test void reembolsoPendienteMantieneRetenido(){pago("approved","released");var r=new Reembolso();r.setEstado(Reembolso.EstadoReembolso.SOLICITADO);when(reembolsos.findByOrdenId(42L)).thenReturn(Optional.of(r));service.compra(42L);assertEquals(MovimientoSaldo.EstadoMovimiento.BLOQUEADO,m.getEstado());}
 @Test void bloqueaDocenteAntesDeOrdenParaEvitarInterbloqueos(){pago("approved","pending");service.compra(42L);var orden=inOrder(bloqueo,ordenes);orden.verify(bloqueo).bloquear(7L);orden.verify(ordenes).bloquear(42L);}
}
